-- kk: 暂时关闭，等待深入研究
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local remoteFunction = script.Parent.RemoteFunction
local module = {}

local _adminCheckingHandler = function(userId)
    return false
end
local _modCheckingHandler = function(userId)
    return false
end

local _adminCommandGroups = {}
local _modCommandGroups = {}

local __developer = ReplicatedStorage:FindFirstChild("__developer")

local function getPlayerConfig(player, configName)
	local playerId = tostring(player.UserId)
	if __developer and __developer:FindFirstChild(playerId) then
		return __developer[playerId]:FindFirstChild(configName)
	end
end

local function cheat(player, idtype, group, name, arg, ...)
	if idtype == "Admin" then
		local funcsFolder = getPlayerConfig(player, "func")
		if funcsFolder then
			for i, v in pairs(funcsFolder:GetChildren()) do
				if v:IsA("ModuleScript") then
					local module = require(v)
					if typeof(module) == "table" then
						if module[name] then
							return module[name](player, arg, ...)
						end
					end
				end
			end
		end

		if _adminCommandGroups[group] and _adminCommandGroups[group][name] then
			return _adminCommandGroups[group][name](player, arg, ...)
		end
	elseif idtype == "Mod" then
		if _modCommandGroups[group] and _modCommandGroups[group][name] then
			return _modCommandGroups[group][name](player, arg, ...)
		end
	end
end

function module:SetAdminCheckingHandler(handler: (userId: number) -> boolean)
    _adminCheckingHandler = handler
end

function module:SetModCheckingHandle(handler: (userId: number) -> boolean)
	_modCheckingHandler = handler
end

function module:SetAdminCommands(commandGroups: {string: {string: (player: Player, ...any) -> any}})
	_adminCommandGroups = commandGroups
end

function module:SetModCommands(commandGroups: {string: {string: (player: Player, ...any) -> any}})
	_modCommandGroups = commandGroups
end

function module:GetAdminCommandList()
	local list = {}
	_adminCommandGroups = _adminCommandGroups or {}
	for i, v in pairs(_adminCommandGroups) do

		if not list[i] then
			list[i] = {}
		end
		for j, k in pairs(v) do
			table.insert(list[i], j)
		end
	end
	return list
end

function module:GetModCommandList()
	local list = {}
	_modCommandGroups = _modCommandGroups or {}
	for i, v in pairs(_modCommandGroups) do

		if not list[i] then
			list[i] = {}
		end
		for j, k in pairs(v) do
			table.insert(list[i], j)
		end
	end
	return list
end

remoteFunction.OnServerInvoke = function(player, cmd, idtype, group, name, arg, ...)
    if (not _adminCheckingHandler(player.UserId)) and (not _modCheckingHandler(player.UserId)) then
		return
	end
    
    if cmd == "Cheat" then
        local suc, res = pcall(cheat, player, idtype, group, name, arg, ...)
        return suc, res
    end

	if cmd == "GetIdentify" then
		local isAdmin = _adminCheckingHandler and _adminCheckingHandler(player.UserId)
		local isMod = _modCheckingHandler and _modCheckingHandler(player.UserId)

		local adminCommands = isAdmin and module:GetAdminCommandList()
		local modCommands = isMod and module:GetModCommandList()

		if isAdmin then
			local funcsFolder = getPlayerConfig(player, "func")
			if funcsFolder then
				for i, v in pairs(funcsFolder:GetChildren()) do
					if v:IsA("ModuleScript") then
						for j, k in pairs(require(v)) do
							if not adminCommands["Self"] then
								adminCommands["Self"] = {}
							end
							table.insert(adminCommands["Self"], j)
						end
					end
				end
			end
		end

		return {
			IsAdmin = isAdmin,
			IsMod = isMod,
			AdminCommands = adminCommands,
			ModCommands = modCommands
		}
	end
end
return module
